<template>
  <f-btn
    :label="$t('apply_default_to_origins')"
    @click="openDialog()"
  />

  <q-dialog v-model="showDialog" persistent>
    <q-card class="width-500">
      <q-toolbar class="secondary-toolbar text-white">
        <q-toolbar-title class="text-weight-bold">{{ $t('apply_default_layout_to_origins') }}</q-toolbar-title>
        <q-btn flat round dense icon="close" @click="closeDialog" />
      </q-toolbar>

      <q-card-section>
        <!-- Warning Banner -->
        <div class="warning-box q-mb-md q-pa-sm">
          <div class="row items-center no-wrap">
            <q-icon name="info" color="primary" size="sm" class="q-mr-sm" />
            <div class="text-caption">{{ $t('default_layout_will_replace_custom') }} </div>
          </div>
        </div>

        <!-- Select Origins Header -->
        <div class="row justify-between items-center q-mb-sm">
          <div class="text-subtitle1 text-weight-medium">
            {{ $t('select_origins') }} ({{ selectedOrigins.length }} {{ $t('selected') }})
          </div>
          <q-btn
            flat
            dense
            color="primary"
            :label="allSelected ? $t('deselect_all') : $t('select_all')"
            @click="toggleSelectAll"
          />
        </div>

        <!-- Origins List -->
        <div class="origins-list">
          <q-item
            v-for="origin in originsList"
            :key="origin.value"
            clickable
            @click="toggleOrigin(origin)"
            class="origin-item"
            :class="{ 'origin-item-selected': selectedOrigins.includes(origin.value) }"
          >
            <q-item-section side>
              <q-checkbox
                v-model="selectedOrigins"
                :val="origin.value"
                color="primary"
                @click.stop
              />
            </q-item-section>

            <q-item-section>
              <q-item-label class="text-weight-medium">{{ origin.label }}</q-item-label>
            </q-item-section>
          </q-item>
        </div>
      </q-card-section>

      <!-- Actions -->
      <q-card-actions class="q-pa-md row q-col-gutter-sm">
        <div class="col-6">
          <q-btn
            outline
            color="primary"
            :label="$t('cancel')"
            class="full-width"
            @click="closeDialog"
          />
        </div>
        <div class="col-6">
          <q-btn
            :label="$t('apply_to') + ' ' + selectedOrigins.length + ' ' + $t('origins')"
            color="primary"
            class="full-width"
            :disable="selectedOrigins.length === 0 || isApplying"
            :loading="isApplying"
            @click="applyToOrigins"
          />
        </div>
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { notify } from 'src/components/notifications/notify'; 
import { formBuilderApiService } from 'src/services';
import { useFormBuilderStore, useLangOriginDropdownStore } from 'src/store/main';

export interface OriginItem {
  value: string;
  label: string;
  hasLayout: boolean;
  lastUpdated: string | null;
  layoutId: string | null;
}

export default defineComponent({
  name: 'ApplyDefaultLayoutToOrigins',
  emits: ['finishUpdate'],
  props: {
    doc_type_key: {
      type: String
    }
  },
  data() {
    return {
      showDialog: false,
      isApplying: false,
      selectedOrigins: [] as string[],
      originsList: [] as OriginItem[],
    };
  },
  computed: {
    allSelected(): boolean {
      return this.originsList.length > 0 &&
             this.selectedOrigins.length === this.originsList.length;
    }
  },
  methods: {
    async openDialog() {
      this.selectedOrigins = [];
      this.showDialog = true;
      await this.loadOriginsList();
    },

    closeDialog() {
      this.showDialog = false;
      this.selectedOrigins = [];
    },

    async loadOriginsList() {
      try {
        await this.getLanguageIfEmpty();

        // Get all layout templates for this doc type
        const layouts = await formBuilderApiService.getAllLayoutTemplates({
          doc_type_key: this.docType
        });

        // Create a map of origin -> layout info
        const layoutMap = new Map<string, { id: string; updatedAt: string }>();
        if (layouts && Array.isArray(layouts)) {
          layouts.forEach((layout: any) => {
            if (layout.doc_origin) {
              layoutMap.set(layout.doc_origin, {
                id: layout.id,
                updatedAt: layout.updated_at || layout.created_at
              });
            }
          });
        }

        // Build origins list from language_origins, excluding the default (empty value)
        this.originsList = this.language_origins
          .filter((origin: any) => origin.value !== '')
          .map((origin: any) => {
            const layoutInfo = layoutMap.get(origin.value);
            return {
              value: origin.value,
              label: origin.label,
              hasLayout: !!layoutInfo,
              lastUpdated: layoutInfo ? this.formatDate(layoutInfo.updatedAt) : null,
              layoutId: layoutInfo ? layoutInfo.id : null
            };
          });

      } catch (err) {
        logError(err);
        notify.error(this.$t('error_loading_origins'));
      }
    },

    formatDate(dateStr: string): string {
      if (!dateStr) return '';
      const date = new Date(dateStr);
      return date.toISOString().split('T')[0];
    },

    toggleOrigin(origin: OriginItem) {
      const index = this.selectedOrigins.indexOf(origin.value);
      if (index === -1) {
        this.selectedOrigins.push(origin.value);
      } else {
        this.selectedOrigins.splice(index, 1);
      }
    },

    toggleSelectAll() {
      if (this.allSelected) {
        this.selectedOrigins = [];
      } else {
        this.selectedOrigins = this.originsList.map(o => o.value);
      }
    },

    async applyToOrigins() {
      let apiData: any = {
          'selected_origins': this.selectedOrigins,
          'doc_type_key': this.doc_type_key,
          'title': 'form builder'
        };
      const response = await formBuilderApiService.applyDefaultLayoutToOrigins(apiData);
      if ( response.success == false ) {
        notify.error(this.$t('error_applying_default_layout'));
        return
      }
      notify.success(this.$t('default_layout_applied_successfully'));
      const updatedOrigins = [...this.selectedOrigins]; // Save before closeDialog clears it
      this.closeDialog();
      this.$emit('finishUpdate', updatedOrigins);
    }
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { docType } = storeToRefs(form_builder_store);

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { language_origins } = storeToRefs(language_origin_dropdown);
    const { getLanguageIfEmpty } = language_origin_dropdown;

    return {
      docType,
      language_origins,
      getLanguageIfEmpty,
      subDocType: ref(''),
    };
  }
});
</script>

<style scoped lang="scss">
.width-500 {
  width: 500px;
  max-width: 95vw;
}

.warning-box {
  background-color: #e0f2fe;
  border: 1px solid #bae6fd;
  border-radius: 8px;

  .body--dark & {
    background-color: rgba(56, 189, 248, 0.15);
    border-color: rgba(56, 189, 248, 0.3);
  }
}

.origins-list {
  max-height: 300px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.origin-item {
  border: 1px solid var(--fb-border-light);
  border-radius: 8px;
  background-color: var(--fb-bg-primary);

  &:hover {
    background-color: var(--fb-bg-hover);
  }
}

.origin-item-selected {
  background-color: var(--dashboard-primary-soft);
  border-color: var(--primary-color);
}
</style>
